def random_latex_command_removal(text, p=0.1, rng=None, seed=None):
    """
    Randomly remove latex commands
    """
    rng = _resolve_rng(rng, seed)
    return re.sub(r'\\[a-zA-Z]+(\{[^}]*\})?', lambda m: m.group(0) if rng.random() > p else '', text)

